@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (our sibling): the dark page turned over. Off-white #eee paper, black ink, white
   cards, #cdcdcd for quiet surfaces and hairlines, the same signal yellow #fff313 with black
   text on it, #c0b400 as the darker yellow. */
:root {
  --background: oklch(0.949 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.943 0.199 105.9);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.848 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.88 0 0);
  --muted-foreground: oklch(0.59 0 0);
  --accent: oklch(0.848 0 0);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.648 0.203 29.3);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.848 0 0);
  --input: oklch(0.754 0 0);
  --ring: oklch(0 0 0);
  --highlight: oklch(0.756 0.16 104.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.943 0.199 105.9);
  --chart-1: oklch(0.943 0.199 105.9);
  --chart-2: oklch(0.756 0.16 104.8);
  --chart-3: oklch(0.648 0.203 29.3);
  --chart-4: oklch(0.413 0 0);
  --chart-5: oklch(0.59 0 0);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.943 0.199 105.9);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.848 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.848 0 0);
  --sidebar-ring: oklch(0 0 0);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  --page-width: 100rem;
  --page-gutter: 4.2667vw;
  --section-y: 7.5rem;
}

/* The outer gutter follows the window: 4.27vw on phones (17px at 390), 2.5vw from laptop
   widths up (36px at 1440), as on the original. */
@media (min-width: 1024px) {
  :root {
    --page-gutter: 2.5vw;
  }
}

/* Dark (faithful): black #000 page, #202020 panels (cards, the expertise band), #323232
   charcoal for raised surfaces and hairlines, off-white #eee text, mid-grey #7d7d7d for quiet
   copy, signal yellow #fff313 with black text on it, #c0b400 as the darker yellow, and the
   yellow as the glow. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(0.949 0 0);
  --card: oklch(0.244 0 0);
  --card-foreground: oklch(0.949 0 0);
  --popover: oklch(0.244 0 0);
  --popover-foreground: oklch(0.949 0 0);
  --primary: oklch(0.943 0.199 105.9);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.317 0 0);
  --secondary-foreground: oklch(0.949 0 0);
  --muted: oklch(0.317 0 0);
  --muted-foreground: oklch(0.59 0 0);
  --accent: oklch(0.317 0 0);
  --accent-foreground: oklch(0.949 0 0);
  --destructive: oklch(0.648 0.203 29.3);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.317 0 0);
  --input: oklch(0.413 0 0);
  --ring: oklch(0.943 0.199 105.9);
  --highlight: oklch(0.756 0.16 104.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.943 0.199 105.9);
  --chart-1: oklch(0.943 0.199 105.9);
  --chart-2: oklch(0.756 0.16 104.8);
  --chart-3: oklch(0.648 0.203 29.3);
  --chart-4: oklch(0.754 0 0);
  --chart-5: oklch(0.59 0 0);
  --sidebar: oklch(0.244 0 0);
  --sidebar-foreground: oklch(0.949 0 0);
  --sidebar-primary: oklch(0.943 0.199 105.9);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.317 0 0);
  --sidebar-accent-foreground: oklch(0.949 0 0);
  --sidebar-border: oklch(0.317 0 0);
  --sidebar-ring: oklch(0.943 0.199 105.9);
}
